head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf05200";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — resultList

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "ul_36", attr: "__html", fn: function () { return ([String(dma_page.get("total")), String(dma_page.get("currentPage")), String(dma_page.get("pageCount"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("총 <strong id=\"totPage\">" + String(dma_page.get("total")) + "</strong>건 <span id=\"totPage1\">(" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + ")</span>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_resultList", fn: function(){ return (!(String(((dma_pageContext.get("resultList") ?? "")) == null ? '' : ((dma_pageContext.get("resultList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_paramSearchWord", fn: function () { return String((dma_pageContext.get("searchWord") ?? "")); } },
        { childId: "ipt_searchWord", fn: function () { return String((dma_pageContext.get("searchWord") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent("ipt_searchWord").focus();
        let pageIndex = $c.util.getComponent('ipt_currentPage').getValue(); if (pageIndex == null) { pageIndex = ''; }
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }
        if (pageIndex === '') {
            $c.util.getComponent('totPage').setLabel("0");
            $c.util.getComponent('totPage1').setLabel("(1/0)");
        }
        $(".search input[type=text]").keypress(async function(e) {
                if (e.keyCode === 13) {
                    await scwin.search();
                }
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05200.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 키 corplist#corpinfolist 를 쓰는 tx 가 2개다(tx_fn_search, tx_fn_goPage)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":1
        ,"mmenu":2
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf05200' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf05200.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_4_onsubmit
 * @description form_4 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_4_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05200.form_4_onsubmit' }); }
};

/**
 * @method
 * @name ipt_searchWord_onkeypress
 * @description ipt_searchWord onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_searchWord_onkeypress = async function(e){
    try {
        const ev = e;
        const event = ev;
        if(event.KeyCode===13) await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05200.ipt_searchWord_onkeypress' }); }
};

/**
 * @method
 * @name ipt_searchWord_onkeyup
 * @description ipt_searchWord 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_searchWord_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        fn_boardCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05200.ipt_searchWord_onkeyup' }); }
};

/**
 * @method
 * @name btn_search_onclick
 * @description btn_search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05200.btn_search_onclick' }); }
};

/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.open_corpView(r["isurCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_search
 * @description search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/corp/corpList.do?method=corpInfoList",
        ref: "dma_searchReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goPage
 * @description go Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goPage = async function () {
    const sbmOptions = {
        id: "tx_fn_goPage",
        method: "post",
        action: "/corp/corpList.do?method=corpInfoList",
        ref: "dma_goPageReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_resultList_fmt_isurCd
 * @description grd result List fmt isur Cd 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_fmt_isurCd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "isur_chk") ?? '') : '');
        if (v !== '#') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "isurCd") : '') ?? '') + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "isurCd") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_resultList.isurCd" }); return String(data ?? ''); }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_searchWord').getValue()) === 0) {
        await $c.win.alert("발행기관명(코드)를 입력하세요");
        $c.util.getComponent("ipt_searchWord").focus();
        $c.util.getComponent('ipt_searchWord').setValue(($c.util.getComponent("ipt_searchWord").getValue() || ''));
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_searchWord').getValue()) <= 2) {
        await $c.win.alert("발행기관명(코드)를 확인하세요");
        $c.util.getComponent("ipt_searchWord").focus();
        $c.util.getComponent('ipt_searchWord').setValue(($c.util.getComponent("ipt_searchWord").getValue() || ''));
        return;
    }
    const frm = (document.JLDINF05200 || { elements: [] });
    frm.action = "/corp/corpList.do?method=corpInfoList";
    frm.target = "_top";
    blockLoading();
    await scwin.tx_fn_search();
};

/**
 * @method
 * @name goPage
 * @description go Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goPage = async function () {
    if (($c.util.getComponent('ipt_searchWord').getValue() == null ? '' : String($c.util.getComponent('ipt_searchWord').getValue())) === '') {
        $c.util.getComponent('ipt_searchWord').setValue($("paramSearchWord").val());
    }
    const frm = (document.JLDINF05200 || { elements: [] });
    frm.action = "/corp/corpList.do?method=corpInfoList";
    blockLoading();
    await scwin.tx_fn_goPage();
};

/**
 * @method
 * @name open_corpView
 * @description open corp View 처리
 * @param {String} ipt_isurCd ipt_isurCd
 * @returns {void}
 * @hidden N
 */
scwin.open_corpView = function (ipt_isurCd) {
    const formName = (document.popupForm || { elements: [] });
    $c.util.getComponent("dma_searchReq").set("isurCd", ipt_isurCd);
    fn_popupCorpView(formName, ipt_isurCd);
};

/**
 * @method
 * @name open_modify
 * @description open modify 처리
 * @param {String} ipt_isurCd ipt_isurCd
 * @returns {void}
 * @hidden N
 */
scwin.open_modify = function (ipt_isurCd) {
    $c.util.getComponent('ipt_isurCd').setValue(ipt_isurCd);
    const formName = (document.popupForm || { elements: [] });
    fn_popupCorpUpdReq(formName, $c.util.getComponent('ipt_isurCd').getValue());
};

/**
 * @method
 * @name open_notCorpUpdMsg
 * @description open not Corp Upd Msg 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.open_notCorpUpdMsg = async function () {
    await $c.win.alert("상장법인은 법인정보를 변경할 수 없습니다.\n법인정보 변경은 해당 상장사 공시 담당자에게 문의하시기 바랍니다.\n문의전화 : 02-3774-8684");
    return;
};

/**
 * @method
 * @name krxpage_pagenavigator_83_onclick
 * @description krxpage_pagenavigator_83 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_83_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_83.page' }); } await scwin.goPage(); };
